import groovy.sql.Sql
import java.sql.SQLException
import org.apache.nifi.processor.io.InputStreamCallback
import io.minio.MinioClient
import io.minio.PutObjectArgs
import io.minio.BucketExistsArgs

// Get the incoming FlowFile
def flowFile = session.get()
if (flowFile == null) {
    return // No FlowFile, do nothing
}

// JDBC Configuration for Trino - UPDATED
def jdbcUrl = 'jdbc:trino://10.10.5.23:8080'
def driverClassName = 'io.trino.jdbc.TrinoDriver'
def user = 'admin'
def password = '' // No password specified

// MinIO Configuration
def minioEndpoint = 'http://10.10.5.63:9000'
def minioAccessKey = 'datalake'
def minioSecretKey = 'gqfxQz1AiAm'
def bucketName = 'mcdonalds'
def hiveTablePath = 's3a://mcdonalds/mcdonalds_internal/'  // Hive table location

// Load the JDBC driver
try {
    log.info("Step 1: Loading JDBC driver...")
    Class.forName(driverClassName)
    log.info("JDBC driver loaded successfully.")
} catch (ClassNotFoundException e) {
    log.error("Error: JDBC Driver not found.", e)
    session.transfer(flowFile, REL_FAILURE)
    return
}

// Establish a connection using Groovy's Sql class
def sql = null
try {
    log.info("Step 2: Connecting to Trino...")
    sql = Sql.newInstance(jdbcUrl, user, password, driverClassName)
    log.info("Connected to Trino successfully.")

    // Step 3: Check if Hive table exists
    log.info("Checking if Hive table 'hive.db_mcd_internal.tbl_mcdonalds_int' exists...")
    def hiveTableExists = sql.firstRow("SHOW TABLES IN hive.db_mcd_internal LIKE 'mcdonalds_int'") != null

    if (!hiveTableExists) {
        log.info("Hive table does not exist. Creating it now...")
        sql.execute """
            CREATE TABLE IF NOT EXISTS hive.db_mcd_internal.tbl_mcdonalds_int (
               dt DATE,
               bill_number VARCHAR(50),
               item_desc VARCHAR(50),
               time VARCHAR(50),
               quantity INTEGER,
               rate INTEGER,
               tax_percent INTEGER,
               discount INTEGER,
               total DOUBLE,
               category VARCHAR(50),
               store_code VARCHAR(50),
               ts VARCHAR(50),
               mobile_no VARCHAR(50),
               delivery_time_min INTEGER,
               payment_type VARCHAR(20),
               cost_price INTEGER,
               speed INTEGER,
               availability INTEGER,
               quality INTEGER,
               hygiene INTEGER,
               service INTEGER,
               order_type VARCHAR(50)
            )
            WITH (
               external_location = '${hiveTablePath}',
               format = 'TEXTFILE',
               textfile_field_separator = ','
            )
        """
        log.info("Hive table created successfully.")
    } else {
        log.info("Hive table already exists.")
    }

    // Step 4: Upload the FlowFile content to MinIO
    log.info("Uploading FlowFile content to MinIO at Hive table location: ${hiveTablePath}...")

    try {
        MinioClient minioClient = MinioClient.builder()
            .endpoint(minioEndpoint)
            .credentials(minioAccessKey, minioSecretKey)
            .build()

        if (!minioClient.bucketExists(BucketExistsArgs.builder().bucket(bucketName).build())) {
            minioClient.makeBucket(bucketName)
            log.info("Bucket '${bucketName}' created.")
        }

        def objectKey = "mcdonalds_internal/${flowFile.getAttribute('filename')}"
        flowFile.read(new InputStreamCallback() {
            @Override
            void process(InputStream inputStream) throws IOException {
                minioClient.putObject(
                    PutObjectArgs.builder()
                        .bucket(bucketName)
                        .object(objectKey)
                        .stream(inputStream, inputStream.available(), -1)
                        .build()
                )
                log.info("File uploaded to MinIO under '${objectKey}'.")
            }
        })

    } catch (Exception e) {
        log.error("Error uploading to MinIO: ${e.message}", e)
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // Step 5: Check if Iceberg table exists
    log.info("Checking if Iceberg table 'iceberg.db_mcd_external.tbl_mcdonalds_ext' exists...")
    def icebergTableExists = sql.firstRow("SHOW TABLES IN iceberg.db_mcd_external LIKE 'mcdonalds_ext'") != null

    if (!icebergTableExists) {
        log.info("Iceberg table does not exist. Creating it now...")
        sql.execute """
            CREATE TABLE IF NOT EXISTS iceberg.db_mcd_external.tbl_mcdonalds_ext (
               dt DATE,
               bill_number VARCHAR(50),
               item_desc VARCHAR(50),
               time VARCHAR(50),
               quantity INTEGER,
               rate INTEGER,
               tax_percent INTEGER,
               discount INTEGER,
               total DOUBLE,
               category VARCHAR(50),
               store_code VARCHAR(50),
               ts VARCHAR(50),
               mobile_no VARCHAR(50),
               delivery_time_min INTEGER,
               payment_type VARCHAR(20),
               cost_price INTEGER,
               speed INTEGER,
               availability INTEGER,
               quality INTEGER,
               hygiene INTEGER,
               service INTEGER,
               order_type VARCHAR(50)
            )
            WITH (
                format = 'ORC',
                format_version = 2,
                location = 's3a://mcdonalds/mcdonalds_external/'
            )
        """
        log.info("Iceberg table created successfully.")
    } else {
        log.info("Iceberg table already exists.")
    }

    // Step 6: Insert data from Hive to Iceberg
    log.info("Checking data in 'hive.db_mcd_internal.tbl_mcdonalds_int' before inserting into Iceberg...")
    def rowCount = sql.firstRow("SELECT COUNT(*) FROM hive.db_mcd_internal.tbl_mcdonalds_int")[0]

    if (rowCount > 0) {
        log.info("Inserting records from 'hive.db_mcd_internal.tbl_mcdonalds_int' to 'iceberg.db_mcd_external.tbl_mcdonalds_ext'...")
        try {
            sql.execute("""
                INSERT INTO iceberg.db_mcd_external.tbl_mcdonalds_ext
                SELECT * FROM hive.db_mcd_internal.tbl_mcdonalds_int
            """)
            log.info("Data inserted into Iceberg table successfully.")
        } catch (SQLException sqlEx) {
            log.error("SQL Exception during insertion: ${sqlEx.message}", sqlEx)
            session.transfer(flowFile, REL_FAILURE)
            return
        }
    } else {
        log.warn("No data found in 'hive.db_mcd_internal.tbl_mcdonalds_int' to insert into Iceberg.")
    }

    // Transfer FlowFile to success after full processing
    session.transfer(flowFile, REL_SUCCESS)

} catch (SQLException sqlEx) {
    log.error("SQL Exception occurred: ${sqlEx.message}", sqlEx)
    session.transfer(flowFile, REL_FAILURE)
} catch (Exception e) {
    log.error("An error occurred: ${e.message}", e)
    session.transfer(flowFile, REL_FAILURE)
} finally {
    if (sql != null) {
        try {
            sql.close()
            log.info("Database connection closed.")
        } catch (Exception e) {
            log.error("Failed to close database connection: ${e.message}", e)
        }
    }
}
